def _parse_filters(filters):
    if isinstance(filters, str):
        try:
            filters = json.loads(filters)
        except Exception:
            filters = {}
    return filters or {}


def _date_bounds(filters):
    date_from = getdate(filters.get("date_from") or nowdate())
    date_to = getdate(filters.get("date_to") or nowdate())
    if date_from > date_to:
        date_from, date_to = date_to, date_from
    return date_from, date_to


def _time_text(value, default):
    value = (value or default).strip()
    if len(value) == 5:
        value += ":00"
    try:
        return datetime.strptime(value, "%H:%M:%S").time()
    except Exception:
        return datetime.strptime(default, "%H:%M:%S").time()


def _history_rows(side, filters):
    date_from, date_to = _date_bounds(filters)
    t_from = _time_text(filters.get("time_from"), "00:00:00")
    t_to = _time_text(filters.get("time_to"), "23:59:59")
    customer = (filters.get("customer") or "").strip()
    item = (filters.get("item") or "").strip()
    source_filter = (filters.get("source_filter") or "All").strip()
    amount_mode = (filters.get("amount_mode") or "Any").strip()
    amount_exact = flt(filters.get("amount_exact"))
    amount_from = flt(filters.get("amount_from"))
    amount_to = flt(filters.get("amount_to"))

    if side == "cashier":
        parent, child, dt_field, user_field = (
            "NKT Cashier Sale", "NKT Cashier Sale Item", "sale_datetime", "cashier"
        )
        status_clause = "p.docstatus=1 AND COALESCE(p.status,'')!='Cancelled'"
        counterpart = "p.matched_customer_order"
    else:
        parent, child, dt_field, user_field = (
            "NKT Customer Order", "NKT Customer Order Item", "creation", "encoder"
        )
        status_clause = "p.docstatus=1 AND COALESCE(p.status,'')!='Cancelled'"
        counterpart = "p.matched_cashier_sale"

    clauses = [
        status_clause,
        f"DATE(p.`{dt_field}`) BETWEEN %(date_from)s AND %(date_to)s",
        f"TIME(p.`{dt_field}`) BETWEEN %(time_from)s AND %(time_to)s",
    ]
    params = {
        "date_from": date_from,
        "date_to": date_to,
        "time_from": t_from,
        "time_to": t_to,
    }

    if customer:
        clauses.append("(p.customer LIKE %(cust)s OR p.customer_name LIKE %(cust)s)")
        params["cust"] = f"%{customer}%"
    if item:
        clauses.append(
            "EXISTS (SELECT 1 FROM `tab%s` ci "
            "WHERE ci.parent=p.name AND ci.parenttype=%%(parenttype)s "
            "AND (ci.item=%%(item_exact)s OR ci.item LIKE %%(item_like)s OR COALESCE(ci.item_name,'') LIKE %%(item_like)s))" % child
        )
        params["parenttype"] = parent
        params["item_exact"] = item
        params["item_like"] = f"%{item}%"
    if source_filter == "Original Sale":
        clauses.append("COALESCE(p.custom_nkt_exchange_generation,0)=0")
    elif source_filter == "Previous Exchange":
        clauses.append("COALESCE(p.custom_nkt_exchange_generation,0)>0")

    if amount_mode == "Exact" and amount_exact > 0:
        clauses.append("ABS(p.grand_total-%(amount_exact)s)<=0.005")
        params["amount_exact"] = amount_exact
    elif amount_mode == "Range":
        if amount_from > 0:
            clauses.append("p.grand_total >= %(amount_from)s")
            params["amount_from"] = amount_from
        if amount_to > 0:
            clauses.append("p.grand_total <= %(amount_to)s")
            params["amount_to"] = amount_to

    query = f"""
        SELECT
            p.name,
            p.customer,
            p.customer_name,
            p.grand_total,
            p.`{dt_field}` AS txn_datetime,
            COALESCE(p.custom_nkt_exchange_generation,0) AS generation,
            p.custom_nkt_exchange_parent,
            {counterpart} AS counterpart,
            GROUP_CONCAT(DISTINCT COALESCE(NULLIF(i.item_name,''),i.item)
                         ORDER BY i.idx SEPARATOR ', ') AS items_text,
            SUM(i.quantity) AS sold_qty
        FROM `tab{parent}` p
        INNER JOIN `tab{child}` i
            ON i.parent=p.name AND i.parenttype='{parent}'
        WHERE {" AND ".join(clauses)}
        GROUP BY p.name
        ORDER BY p.`{dt_field}` DESC, p.name DESC
        LIMIT 100
    """
    return frappe.db.sql(query, params, as_dict=True)


def _prior_return_summary(customer_order, side):
    if not customer_order:
        return {}
    side_label = "Cashier" if str(side).lower() == "cashier" else "Encoder"

    rows = frappe.db.sql(
        """
        SELECT
            ri.item,
            ri.original_source_warehouse,
            SUM(COALESCE(ri.return_quantity,0)) AS qty
        FROM `tabNKT Customer Return` r
        INNER JOIN `tabNKT Customer Return Item` ri
            ON ri.parent=r.name AND ri.parenttype='NKT Customer Return'
        WHERE r.docstatus=1
          AND r.customer_order=%s
        GROUP BY ri.item, ri.original_source_warehouse
        """,
        customer_order,
        as_dict=True,
    )
    result = {
        (x.item, x.original_source_warehouse or ""): flt(x.qty)
        for x in rows
    }

    if frappe.db.exists("DocType", "NKT Return Exchange Declaration"):
        c7_rows = frappe.db.sql(
            """
            SELECT
                i.item,
                i.original_source_warehouse,
                SUM(COALESCE(i.quantity,0)) AS qty
            FROM `tabNKT Return Exchange Declaration` d
            INNER JOIN `tabNKT Return Exchange Returned Item` i
              ON i.parent=d.name
             AND i.parenttype='NKT Return Exchange Declaration'
             AND i.parentfield='returned_items'
            WHERE d.docstatus=1
              AND d.side=%s
              AND d.old_customer_order=%s
              AND d.posting_status='Posted'
            GROUP BY i.item, i.original_source_warehouse
            """,
            (side_label, customer_order),
            as_dict=True,
        )
        for x in c7_rows:
            key = (x.item, x.original_source_warehouse or "")
            result[key] = flt(result.get(key)) + flt(x.qty)

    return result

def _detail(side, source_name):
    if side == "cashier":
        p = frappe.get_doc("NKT Cashier Sale", source_name)
        counterpart = p.get("matched_customer_order")
        child_rows = p.get("items") or []
        dt = p.sale_datetime
        generation = cint(p.get("custom_nkt_exchange_generation"))
        if generation > 0 and flt(p.get("custom_nkt_lineage_money_basis")) + flt(p.get("custom_nkt_lineage_account_basis")) > TOLERANCE:
            money_basis = flt(p.get("custom_nkt_lineage_money_basis"))
            account_basis = flt(p.get("custom_nkt_lineage_account_basis"))
        else:
            money_basis = sum(flt(x.amount) for x in (p.get("payments") or []) if x.payment_method != "Account")
            account_basis = sum(flt(x.amount) for x in (p.get("payments") or []) if x.payment_method == "Account")
    else:
        p = frappe.get_doc("NKT Customer Order", source_name)
        counterpart = p.get("matched_cashier_sale")
        child_rows = p.get("items") or []
        dt = p.creation
        generation = cint(p.get("custom_nkt_exchange_generation"))
        if generation > 0 and flt(p.get("custom_nkt_lineage_money_basis")) + flt(p.get("custom_nkt_lineage_account_basis")) > TOLERANCE:
            money_basis = flt(p.get("custom_nkt_lineage_money_basis"))
            account_basis = flt(p.get("custom_nkt_lineage_account_basis"))
        else:
            money_basis = sum(flt(x.amount) for x in (p.get("declared_payments") or []) if x.payment_method != "Account")
            account_basis = sum(flt(x.amount) for x in (p.get("declared_payments") or []) if x.payment_method == "Account")

    prior = _prior_return_summary(counterpart if side == "cashier" else p.name, side)
    items = []
    for row in child_rows:
        key = (row.item, row.source_warehouse or "")
        returned = flt(prior.get(key))
        available = max(flt(row.quantity) - returned, 0)
        mapping = frappe.db.get_value(
            "Item",
            row.item,
            ["nkt_stock_form","nkt_standard_sack_weight_kg","nkt_damaged_item","nkt_fraction_item"],
            as_dict=True,
        ) or frappe._dict()
        items.append({
            "source_row": row.name,
            "item": row.item,
            "item_name": row.item_name,
            "original_qty": flt(row.quantity),
            "previously_returned_qty": returned,
            "available_qty": available,
            "uom": row.uom,
            "original_rate": flt(row.get("final_rate") or row.get("rate") or row.get("standard_rate")),
            "source_warehouse": row.source_warehouse,
            "damaged_item": mapping.nkt_damaged_item,
            "fraction_item": mapping.nkt_fraction_item,
            "standard_sack_weight_kg": flt(mapping.nkt_standard_sack_weight_kg),
        })

    return {
        "name": p.name,
        "counterpart": counterpart,
        "customer": p.customer,
        "customer_name": p.customer_name or frappe.db.get_value("Customer", p.customer, "customer_name"),
        "date": str(getdate(dt)),
        "time": dt.strftime("%H:%M:%S") if hasattr(dt, "strftime") else "",
        "total": flt(p.grand_total),
        "generation": generation,
        "money_basis": min(flt(money_basis), flt(p.grand_total)),
        "account_basis": max(min(flt(account_basis), flt(p.grand_total)), 0),
        "items": items,
    }


@frappe.whitelist()
def get_return_entry_options(side):
    side = _require_side(side)
    items = frappe.db.sql(
        """
        SELECT name, item_name
        FROM `tabItem`
        WHERE disabled=0
          AND is_stock_item=1
          AND COALESCE(nkt_stock_form,'') IN ('', 'Saleable Sack')
        ORDER BY item_name, name
        LIMIT 1000
        """,
        as_dict=True,
    )
    warehouses = frappe.db.sql(
        """
        SELECT
            name,
            COALESCE(NULLIF(custom_nkt_fast_label,''),name) AS label,
            custom_nkt_fulfillment_type AS fulfillment_type
        FROM `tabWarehouse`
        WHERE disabled=0
          AND is_group=0
          AND COALESCE(custom_nkt_fulfillment_type,'')
              IN ('Immediate Retail Deduction','External Warehouse Release')
        ORDER BY label, name
        """,
        as_dict=True,
    )
    label_counts = {}
    for row in warehouses:
        label_counts[row.label] = label_counts.get(row.label, 0) + 1
    for row in warehouses:
        row.exact_name = row.name
        if label_counts.get(row.label, 0) > 1:
            row.label = f"{row.label} — {row.name}"
    return {"items":items,"warehouses":warehouses}


@frappe.whitelist()
def get_return_filter_options(side):
    _require_side(side)
    items = frappe.db.sql(
        """
        SELECT name, item_name
        FROM `tabItem`
        WHERE disabled=0
          AND is_stock_item=1
          AND COALESCE(nkt_stock_form,'') IN ('', 'Saleable Sack')
        ORDER BY item_name, name
        LIMIT 1000
        """,
        as_dict=True,
    )
    return {"items": items}


@frappe.whitelist()
def search_return_history(side, filters=None):
    side = _require_side(side)
    filters = _parse_filters(filters)
    rows = _history_rows(side, filters)
    out = []
    for row in rows:
        detail = _detail(side, row.name)
        available = sum(flt(x["available_qty"]) for x in detail["items"])
        out.append({
            "name": row.name,
            "date": detail["date"],
            "time": detail["time"],
            "customer": row.customer,
            "customer_name": row.customer_name,
            "total": flt(row.grand_total),
            "generation": cint(row.generation),
            "items_text": row.items_text or "",
            "has_prior_return": any(flt(x["previously_returned_qty"]) > TOLERANCE for x in detail["items"]),
            "available_text": f"{available:g} total unit(s)",
        })
    return {"version": VERSION, "rows": out}


@frappe.whitelist()
def get_return_history_detail(side, source_name):
    side = _require_side(side)
    dt = "NKT Cashier Sale" if side == "cashier" else "NKT Customer Order"
    if not source_name or not frappe.db.exists(dt, source_name):
        frappe.throw(_("The selected OLD ORDER no longer exists."))
    return _detail(side, source_name)


@frappe.whitelist()
def get_replacement_rate(side, old_source, old_item, new_item, same_item_defect=0):
    side = _require_side(side)
    if not new_item:
        frappe.throw(_("Replacement Item is required."))
    if cint(same_item_defect) and old_item == new_item:
        detail = _detail(side, old_source)
        for row in detail["items"]:
            if row["item"] == old_item:
                return {
                    "rate": flt(row["original_rate"]),
                    "rate_source": "Original Sale Rate",
                }
    rate = frappe.db.get_value(
        "Item Price",
        {"item_code": new_item, "price_list": "Standard Selling", "selling": 1},
        "price_list_rate",
    )
    return {"rate": flt(rate), "rate_source": "Current Selling Rate"}


@frappe.whitelist()
def install():
    frappe.set_user("Administrator")
    for old_script in (
        "NKT Cashier Return Exchange V2.0C.7.1",
        "NKT Encoder Return Exchange V2.0C.7.1",
        "NKT Cashier Return Exchange V2.0C.7.4",
        "NKT Encoder Return Exchange V2.0C.7.4",
        "NKT Cashier Return Exchange V2.0C.7.4.1",
        "NKT Encoder Return Exchange V2.0C.7.4.1",
        "NKT Cashier Return Exchange V2.0C.7.4.2",
        "NKT Encoder Return Exchange V2.0C.7.4.2",
        "NKT Cashier Return Exchange V2.0C.7.4.3",
        "NKT Encoder Return Exchange V2.0C.7.4.3",
        "NKT Cashier Return Exchange V2.0C.7.4.4",
        "NKT Encoder Return Exchange V2.0C.7.4.4",
        "NKT Cashier Return Exchange V2.0C.7.4.6",
        "NKT Encoder Return Exchange V2.0C.7.4.6",
        "NKT Cashier Return Exchange V2.0C.7.4.9",
        "NKT Encoder Return Exchange V2.0C.7.4.9",
        "NKT Cashier Return Exchange V2.0C.7.6.1",
        "NKT Encoder Return Exchange V2.0C.7.6.1",
    ):
        if old_script not in {CASHIER_SCRIPT, ENCODER_SCRIPT} and frappe.db.exists("Client Script", old_script):
            frappe.db.set_value("Client Script", old_script, "enabled", 0, update_modified=False)
    # C7.10.2: exactly one active Return/Exchange Client Script per screen.
    # A superseded script left enabled will attach a second set of delegated
    # input handlers with a different JS state object and make rows disappear
    # or revert while the operator types.
    for screen, current_script in (
        (CASHIER_SCREEN, CASHIER_SCRIPT),
        (ENCODER_SCREEN, ENCODER_SCRIPT),
    ):
        for script_name in frappe.get_all(
            "Client Script",
            filters={"dt": screen, "enabled": 1},
            pluck="name",
        ):
            if script_name != current_script:
                frappe.db.set_value(
                    "Client Script",
                    script_name,
                    "enabled",
                    0,
                    update_modified=False,
                )

    c61 = frappe.get_attr("nkt_operations.nkt_store_operations.features.cashier.shift_report.verify")()
    c62 = frappe.get_attr("nkt_operations.nkt_store_operations.features.cashier.encoder_zout.verify")()
    c63 = frappe.get_attr("nkt_operations.nkt_store_operations.features.cashier.reconciliation.verify")()
    if not c61.get("passed") or not c62.get("passed") or not c63.get("passed"):
        frappe.throw(_("Accepted C6 baseline is not passing; refusing C7.1 install."))

    fields = _ensure_lineage_fields()
    _ensure_screen(CASHIER_SCREEN, SIDE_ROLE["cashier"])
    _ensure_screen(ENCODER_SCREEN, SIDE_ROLE["encoder"])
    _ensure_client_script(CASHIER_SCRIPT, CASHIER_SCREEN, CASHIER_JS)
    _ensure_client_script(ENCODER_SCRIPT, ENCODER_SCREEN, ENCODER_JS)
    frappe.db.commit()
    frappe.clear_cache()
    return {
        "version": VERSION,
        "installed": True,
        "screens": [CASHIER_SCREEN, ENCODER_SCREEN],
        "lineage_fields": fields,
        "posting_enabled": True,
        "business_records_created": False,
    }


@frappe.whitelist()
def verify():
    errors = []
    for screen in (CASHIER_SCREEN, ENCODER_SCREEN):
        if not frappe.db.exists("DocType", screen):
            errors.append("Missing screen: " + screen)
    for name, dt, needles in (
        (CASHIER_SCRIPT, CASHIER_SCREEN, ["Customer Name","OLD ORDER","NEW ORDER","PAYMENT SETTLEMENT","RETURN SETTLEMENT","Split Amount","Cash Tendered","full Difference Due","PAYMENT OK","REFUND OK","sync_new_rows_from_dom","previewPayload","independent reconciliation","ERP Warehouse","Split payment ON","Repeated F11 will not create zero-value rows","final balancing row","submitRequestId","submit_request_id","idempotent_replay"]),
        (ENCODER_SCRIPT, ENCODER_SCREEN, ["Customer Name","Time From","Time To","OLD ORDER","NEW ORDER","Preview Settlement","Submit Return / Exchange","My Recent","PAYMENT SETTLEMENT","RETURN SETTLEMENT","Split Amount","Difference Due","AMOUNT DUE BACK","PAYMENT OK","REFUND OK","OVERPAYMENT","Balance Remaining","Refund Money — unavailable","displayed_rate_source","Split payment ON","Repeated F11 will not create zero-value rows","final balancing row","submitRequestId","submit_request_id","idempotent_replay"]),
    ):
        row = frappe.db.get_value("Client Script", name, ["dt","enabled","script"], as_dict=True)
        if not row or row.dt != dt or not cint(row.enabled):
            errors.append("Missing client script: " + name)
        else:
            script_text = row.script or ""
            script_folded = script_text.casefold()
            for needle in needles:
                if str(needle).casefold() not in script_folded:
                    errors.append(f"{name} missing {needle}")

    for dt in ("NKT Cashier Sale","NKT Customer Order"):
        meta = frappe.get_meta(dt)
        for field in (
            "custom_nkt_is_exchange_order",
            "custom_nkt_exchange_generation",
            "custom_nkt_exchange_parent",
            "custom_nkt_exchange_origin",
            "custom_nkt_source_return_entry",
            "custom_nkt_lineage_money_basis",
            "custom_nkt_lineage_account_basis",
        ):
            if not meta.has_field(field):
                errors.append(f"{dt} missing {field}")

    mapped = frappe.db.sql(
        """
        SELECT COUNT(*)
        FROM `tabItem`
        WHERE COALESCE(nkt_damaged_item,'')!=''
           OR COALESCE(nkt_fraction_item,'')!=''
        """
    )[0][0]
    if not mapped:
        errors.append("No designated Damaged/Fraction item mappings found.")

    c61 = frappe.get_attr("nkt_operations.nkt_store_operations.features.cashier.shift_report.verify")()
    c62 = frappe.get_attr("nkt_operations.nkt_store_operations.features.cashier.encoder_zout.verify")()
    c63 = frappe.get_attr("nkt_operations.nkt_store_operations.features.cashier.reconciliation.verify")()
    if not c61.get("passed"): errors.append("C6.1 regression.")
    if not c62.get("passed"): errors.append("C6.2 regression.")
    if not c63.get("passed"): errors.append("C6.3 regression.")

    for screen, expected_script in (
        (CASHIER_SCREEN, CASHIER_SCRIPT),
        (ENCODER_SCREEN, ENCODER_SCRIPT),
    ):
        enabled_scripts = frappe.get_all(
            "Client Script",
            filters={"dt": screen, "enabled": 1},
            pluck="name",
        )
        if enabled_scripts != [expected_script]:
            errors.append(
                f"{screen} must have exactly one enabled Client Script "
                f"({expected_script}); found {enabled_scripts}"
            )

    preview = {}
    for side in ("cashier","encoder"):
        try:
            # Administrator is allowed on both sides.
            rows = _history_rows(side, {
                "date_from": frappe.utils.add_days(nowdate(), -30),
                "date_to": nowdate(),
                "time_from": "00:00",
                "time_to": "23:59",
                "source_filter": "All",
                "amount_mode": "Any",
            })
            preview[side] = {
                "count": len(rows),
                "sample": _detail(side, rows[0].name) if rows else None,
            }
        except Exception as exc:
            errors.append(f"{side} preview failed: {exc}")

    return {
        "version": VERSION,
        "posting_enabled": True,
        "damaged_fraction_mapping_count": int(mapped),
        "c6_1_regression_passed": bool(c61.get("passed")),
        "c6_2_regression_passed": bool(c62.get("passed")),
        "c6_3_regression_passed": bool(c63.get("passed")),
        "preview": preview,
        "errors": errors,
        "passed": not errors,
    }
